from src.nodes.base import BaseNode
from src.runtime.assets.vector_search import (
    get_catalog_vector_index_builder, get_asset_vector_store,
)

class Hou_Mcp_Vector_Index(BaseNode):
    name = "hou_mcp_vector_index"

    def __init__(self):
        super().__init__()
        # [AUTO-GENERATED-PORTS-START]
        self.add_input("action",   "string", widget_type="text", default="build_full")
        self.add_input("asset_id", "string", widget_type="text")
        self.add_input("limit",    "int",    widget_type="int", default=10000)
        self.add_output("indexed",    "int")
        self.add_output("store_size", "int")
        self.add_output("ok",         "bool")
        self.add_output("result",     "any")
        # [AUTO-GENERATED-PORTS-END]

    async def execute(self, inputs):
        action   = str(inputs.get("action") or "build_full").strip().lower()
        asset_id = str(inputs.get("asset_id") or "").strip()
        limit    = int(inputs.get("limit") or 10000)
        try:
            builder = get_catalog_vector_index_builder()
            if action == "rebuild":
                result = builder.rebuild_index()
                ok = result.ok
                indexed = result.indexed
            elif action == "update_asset":
                ok = builder.update_asset_index(asset_id)
                result_dict = {"updated": ok, "asset_id": asset_id}
                return {"indexed": 1 if ok else 0, "store_size": get_asset_vector_store().size(), "ok": ok, "result": result_dict, "exec_out": True}
            elif action == "stats":
                stats = builder.get_statistics()
                return {"indexed": stats.get("store_size", 0), "store_size": stats.get("store_size", 0), "ok": True, "result": stats, "exec_out": True}
            else:  # build_full
                result = builder.build_full_index(limit=limit)
                ok = result.ok
                indexed = result.indexed
            return {
                "indexed":    indexed,
                "store_size": get_asset_vector_store().size(),
                "ok":         ok,
                "result":     result.to_dict() if hasattr(result, 'to_dict') else {},
                "exec_out":   True,
            }
        except Exception as e:
            self.log_error(f"hou_mcp_vector_index failed: {e}")
            return {"indexed": 0, "store_size": 0, "ok": False, "result": {}, "exec_out": True}

def register_node():
    return Hou_Mcp_Vector_Index
